(99, 6, 1, 99, 0, 'completed', '实验方案 v99：多模态融合—复杂脑网络抑郁研究', '针对稿件《复杂脑网络在抑郁症研究中的应用》，本方案第99版聚焦多模态融合，静息态 fMRI + 图论（全局/局部效率、聚类系数）；HAMD 分层；终点为组间拓扑差异及症状相关。', '## 研究问题\n验证多模态融合相关指标能否区分抑郁与健康对照。\n\n## 被试与数据\nN≈79；3T MRI，静息态8min。\n\n## 分析\n预处理→建图（Schaefer-100）→FDR。\n\n## 成功标准\n主要指标 p<0.05。', NULL, NULL, 'md', JSON_OBJECT('manuscript_title', '复杂脑网络在抑郁症研究中的应用', 'batch', 'demo100', 'idx', 99), '{"baseline": ["健康对照", "未治疗抑郁"], "seed": 99}', '2026-10-12 03:39:00', '2026-10-12 03:39:00'),
(100, 6, 1, 100, 1, 'draft', '实验方案 v100：可重复性与样本量—复杂脑网络抑郁研究', '针对稿件《复杂脑网络在抑郁症研究中的应用》，本方案第100版聚焦可重复性与样本量，静息态 fMRI + 图论（全局/局部效率、聚类系数）；HAMD 分层；终点为组间拓扑差异及症状相关。', '## 研究问题\n验证可重复性与样本量相关指标能否区分抑郁与健康对照。\n\n## 被试与数据\nN≈80；3T MRI，静息态8min。\n\n## 分析\n预处理→建图（Schaefer-100）→FDR。\n\n## 成功标准\n主要指标 p<0.05。', NULL, NULL, 'md', JSON_OBJECT('manuscript_title', '复杂脑网络在抑郁症研究中的应用', 'batch', 'demo100', 'idx', 100), '{"baseline": ["健康对照", "未治疗抑郁"], "seed": 100}', '2026-10-12 03:40:00', '2026-10-12 03:40:00');
