-- Demo: 100 x paper_output_experiment_plan + 100 x paper_output_literature_review
-- manuscript_id=6, user_id=1, 复杂脑网络在抑郁症研究中的应用
--
-- 列表为空时请先执行（不要只贴 experiment_plan 的 INSERT）：
--   SELECT id, user_id, status FROM paper_manuscript WHERE id=6;
--   SELECT COUNT(*) FROM paper_output_experiment_plan WHERE manuscript_id=6 AND status<>'deleted';
--   SELECT id, manuscript_id FROM paper_output_experiment_plan WHERE id=1;
-- 常见原因：① id 1–100 主键冲突导致 INSERT 整段失败；② 未用 user_id=1 登录；
-- ③ 侧栏未选中 id=6 的论文；④ paper_manuscript 非 active 或不属于当前用户。
-- 推荐：整文件执行（含 DELETE + 文献综述 experiment_plan_id 关联），勿单独执行 VALUES。
-- 文献综述需先执行：
--   docs/migrations/20251080_literature_review_from_attachments.sql
--   docs/migrations/20251081_literature_review_drop_legacy_columns.sql
--
-- 若 id 1–100 已被其它稿件占用，先删本稿 demo 或改脚本里的 id 区间
DELETE FROM paper_output_literature_review WHERE manuscript_id=6;
DELETE FROM paper_output_experiment_plan WHERE manuscript_id=6;

SET NAMES utf8mb4;



